# (value, label) pairs for a model field, in the order a person would scan.
CHOICES: list[tuple[str, str]] = sorted(
    ((name, icon.label) for name, icon in ICONS.items()),
    key=lambda pair: pair[1],
)


class IconMixin:
    """
    Gives a model with an ``icon`` name field the two paths its template needs.

    Both are "" when the field is empty or names an icon that is no longer in
    the set, so a template guarded with ``{% if row.icon_path %}`` drops the
    ``<span class="attr-card__icon">`` wrapper entirely instead of rendering an
    empty one.
    """

    @property
    def _icon(self) -> Icon | None:
        return ICONS.get(self.icon or "")

    @property
    def icon_path(self) -> str:
        icon = self._icon
        return icon.path if icon else ""

    @property
    def icon_echo(self) -> str:
        icon = self._icon
        return icon.echo if icon else ""
